@keyframes bounce{0%,100%{transform:translateY(0)}50%{transform:translateY(8px)}}
.section{padding:4rem 1.5rem;max-width:1000px;margin:0 auto;min-height:80vh;display:flex;flex-direction:column;justify-content:center}
.section-title{font-size:clamp(1.5rem,4vw,2.5rem);font-weight:700;color:#3a281e;margin-bottom:0.75rem}
.section-desc{font-size:1.1rem;color:#6b5a4a;line-height:1.7;margin-bottom:2.5rem;max-width:700px}
.visual-container{width:100%;display:flex;justify-content:center;align-items:center;padding:1.5rem 0}
.visual-container svg{width:100%;max-width:700px;height:auto}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1.5rem;margin-top:2rem}
.card{background:#fff;border-radius:12px;padding:1.75rem;box-shadow:0 2px 12px rgba(0,0,0,0.06);border:1px solid rgba(0,0,0,0.04)}
.card h3{font-size:1.1rem;font-weight:600;color:#3a281e;margin-bottom:0.5rem}
.card p{font-size:0.95rem;color:#6b5a4a;line-height:1.6}
.card .highlight{color:#c44528;font-weight:600}
.card .green{color:#2a7a2a;font-weight:600}
.story-block{background:#fff;border-radius:12px;padding:2rem;margin:1.5rem 0;border-left:4px solid #2a7a2a;box-shadow:0 2px 8px rgba(0,0,0,0.04)}
.story-block h4{font-size:1rem;color:#2a7a2a;margin-bottom:0.5rem}
.story-block p{font-size:0.95rem;color:#6b5a4a;line-height:1.7}
.compare-box{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin:1.5rem 0}
.compare-item{background:#fff;border-radius:10px;padding:1.5rem;border:1px solid #e0d5c8}
.compare-item h4{font-size:1rem;margin-bottom:0.5rem}
.compare-item .num{font-size:2rem;font-weight:700}
.compare-item .num.red{color:#c44528}
.compare-item .num.green{color:#2a7a2a}
.feedback-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:1rem;margin:1.5rem 0}
.feedback-item{background:#fff;border-radius:10px;padding:1.25rem;text-align:center;border:1px solid #e0d5c8}
.feedback-item .quote{font-size:0.9rem;color:#6b5a4a;font-style:italic;margin-bottom:0.75rem;line-height:1.5}
.feedback-item .author{font-size:0.8rem;color:#8a7a6a}
.feedback-item .emoji{font-size:1.5rem;margin-bottom:0.5rem}
.tag{display:inline-block;padding:0.2rem 0.6rem;border-radius:4px;font-size:0.75rem;font-weight:600;margin:0.15rem}
.tag.green{background:#e0f0e0;color:#2a7a2a}
.tag.red{background:#f0e0e0;color:#c44528}
.tag.amber{background:#f0e8d0;color:#a07020}
.lesson-list{list-style:none;padding:0}
.lesson-list li{position:relative;padding:0.75rem 0 0.75rem 1.5rem;border-bottom:1px solid #f0e8e0;font-size:0.95rem;color:#3a281e;line-height:1.5}
.lesson-list li::before{content:'';position:absolute;left:0;top:1.15rem;width:8px;height:8px;border-radius:50%;background:#2a7a2a}
