<!-- ============ 成本对比 ============ -->
<section class="section">
  <h2 class="section-title">成本对比</h2>
  <p class="section-desc">外出学习 vs 自己学，差距有多大？</p>
  <div class="compare-box">
    <div class="compare-item">
      <h4>外出学习</h4>
      <div class="num red">4,000 - 5,000</div>
