{"command": "curl -sL "https://www.douyin.com/video/7664184267388389873?previous_page=app_code_link" -A "Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1" -o /tmp/dy.html 2>/dev/null && python3 -c "
import re
with open('/tmp/dy.html','r') as f:
    html = f.read()
# Try to find title
t = re.search(r'<title[^>]*>(.*?)</title>', html, re.DOTALL)
if t: print('TITLE:', t.group(1).strip()[:300])
# Look for any desc-like content
d = re.search(r'\"desc\":\"([^\"]+)\"', html)
if d: print('DESC:', d.group(1)[:300])
else:
    # Look for any Chinese text content
    texts = re.findall(r'>([^<]{20,200})<', html)
    for t in texts:
        if any('\u4e00' <= c <= '\u9fff' for c in t):
            print('TEXT:', t.strip()[:200])
" 2>&1 | head -20", "timeout": 10}

