{"content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>三环选题系统 · 旋转矩阵</title>
<style>
*,*::before,*::after{margin:0;padding:0;box-sizing:border-box}
body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Noto Sans SC","PingFang SC","Microsoft YaHei",sans-serif;background:#0d0d1a;color:#e0d8d0;overflow-x:hidden}
.hero{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:2rem;text-align:center;background:radial-gradient(ellipse at center,#1a1a3a 0%,#0d0d1a 70%)}
.hero h1{font-size:clamp(2rem,5vw,3.5rem);font-weight:700;background:linear-gradient(135deg,#f0d8c0,#ff8a5c);-webkit-background-clip:text;-webkit-text-fill-color:transparent;margin-bottom:1rem}
.hero .sub{font-size:1.1rem;color:#8a7a6a;max-width:500px;line-height:1.6;margin-bottom:2rem}
.hero .input-area{display:flex;gap:0.75rem;flex-wrap:wrap;justify-content:center}
.hero input{padding:0.85rem 1.5rem;border-radius:50px;border:1px solid #3a2a2a;background:#1a1a2a;color:#e0d8d0;font-size:1rem;width:280px;outline:none;transition:border-color 0.3s}
.hero input:focus{border-color:#ff8a5c}
.hero button{padding:0.85rem 2rem;border-radius:50px;border:none;background:linear-gradient(135deg,#ff6a3c,#ff8a5c);color:#fff;font-size:1rem;font-weight:600;cursor:pointer;transition:transform 0.2s,box-shadow 0.2s}
.hero button:hover{transform:scale(1.05);box-shadow:0 4px 20px rgba(255,138,92,0.3)}
.hero button:active{transform:scale(0.98)}
#wheel-section{display:none;padding:2rem 1.5rem;max-width:1100px;margin:0 auto}
.wheel-header{text-align:center;margin-bottom:2rem}
.wheel-header h2{font-size:1.8rem;color:#f0d8c0;margin-bottom:0.5rem}
.wheel-header p{color:#8a7a6a;font-size:1rem}
.wheel-container{position:relative;width:100%;max-width:700px;margin:0 auto;aspect-ratio:1}
.wheel-container svg{width:100%;height:100%}
.controls{display:flex;gap:1rem;justify-content:center;margin-top:2rem;flex-wrap:wrap}
.controls button{padding:0.75rem 2rem;border-radius:50px;border:none;font-size:1rem;font-weight:600;cursor:pointer;transition:all 0.2s}
.btn-spin{background:linear-gradient(135deg,#ff6a3c,#ff8a5c);color:#fff}
.btn-spin:hover{box-shadow:0 4px 20px rgba(255,138,92,0.3);transform:scale(1.05)}
.btn-auto{background:linear-gradient(135deg,#3a6a3a,#5a9a5a);color:#fff}
.btn-auto:hover{box-shadow:0 4px 20px rgba(90,154,90,0.3);transform:scale(1.05)}
.btn-export{background:linear-gradient(135deg,#3a3a6a,#5a5a9a);color:#fff}
.btn-export:hover{box-shadow:0 4px 20px rgba(90,90,154,0.3);transform:scale(1.05)}

.results{display:none;padding:2rem 1.5rem;max-width:1100px;margin:0 auto}
.results-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.5rem;flex-wrap:wrap;gap:1rem}
.results-header h2{font-size:1.6rem;color:#f0d8c0}
.results-header .count{color:#8a7a6a;font-size:0.9rem}
.topic-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:1rem}
.topic-card{background:#1a1a2a;border-radius:12px;padding:1.25rem;border:1px solid #2a2a3a;transition:all 0.2s;cursor:default}
.topic-card:hover{border-color:#ff8a5c;box-shadow:0 0 20px rgba(255,138,92,0.08)}
.topic-card .tag{display:inline-block;padding:0.15rem 0.5rem;border-radius:4px;font-size:0.7rem;font-weight:600;margin-bottom:0.5rem}
.tag-flow{background:#ff6a3c20;color:#ff8a5c;border:1px solid #ff6a3c40}
.tag-convert{background:#3a6a3a20;color:#5a9a5a;border:1px solid #3a6a3a40}
.tag-hook{background:#3a3a6a20;color:#7a7afa;border:1px solid #3a3a6a40}
.topic-card .title{font-size:1rem;font-weight:600;color:#f0d8c0;margin-bottom:0.5rem;line-height:1.4}
.topic-card .meta{font-size:0.8rem;color:#6a5a4a;margin-bottom:0.75rem}
.topic-card .hook{font-size:0.85rem;color:#7a7afa;padding:0.5rem 0.75rem;background:#1a1a3a;border-radius:8px;border-left:3px solid #5a5a9a;line-height:1.4;margin-bottom:0.5rem}
.topic-card .hook::before{content:'钩子: ';color:#5a5a9a;font-weight:600}
.topic-card .reason{font-size:0.8rem;color:#6a5a4a;line-height:1.4}
.topic-card .kw{display:inline-block;padding:0.1rem 0.4rem;background:#2a2a3a;border-radius:3px;font-size:0.7rem;color:#8a7a6a;margin:0.1rem}

.strategy-panel{display:none;padding:2rem 1.5rem;max-width:1100px;margin:0 auto}
.strategy-panel h2{font-size:1.6rem;color:#f0d8c0;margin-bottom:1.5rem;text-align:center}
.strategy-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:1rem}
.strategy-card{background:#1a1a2a;border-radius:10px;padding:1.25rem;border:1px solid #2a2a3a}
.strategy-card h3{font-size:1rem;color:#f0d8c0;margin-bottom:0.5rem}
.strategy-card .desc{font-size:0.85rem;color:#8a7a6a;line-height:1.5;margin-bottom:0.75rem}
.strategy-card .methods{font-size:0.8rem;color:#6a5a4a}
.strategy-card .methods li{margin-bottom:0.25rem;padding-left:0.5rem}

.hook-panel{display:none;padding:2rem 1.5rem;max-width:1100px;margin:0 auto}
.hook-panel h2{font-size:1.6rem;color:#f0d8c0;margin-bottom:1rem;text-align:center}
.hook-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:1rem}
.hook-card{background:#1a1a2a;border-radius:10px;padding:1.25rem;border:1px solid #2a2a3a}
.hook-card .num{display:inline-block;width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg,#ff6a3c,#ff8a5c);color:#fff;text-align:center;line-height:28px;font-size:0.8rem;font-weight:700;margin-bottom:0.5rem}
.hook-card .name{font-size:0.9rem;color:#f0d8c0;font-weight:600;margin-bottom:0.3rem}
.hook-card .formula{font-size:0.8rem;color:#8a7a6a;font-family:monospace;margin-bottom:0.3rem}
.hook-card .example{font-size:0.8rem;color:#5a9a5a;line-height:1.4}

footer{text-align:center;padding:2rem;color:#4a3a3a;font-size:0.8rem}

/* Spin indicator */
.spin-count{text-align:center;color:#6a5a4a;font-size:0.9rem;margin-top:0.5rem}

@media(max-width:600px){
  .topic-grid,.strategy-list,.hook-grid{grid-template-columns:1fr}
  .hero input{width:100%}
}
</style>
</head>
<body>

