// ============================================================
// CORE: Topic Generation Engine
// ============================================================
function generateTopic(industry) {
  const data = INDUSTRY_DATA[industry] || INDUSTRY_DATA.default;
  const kw1 = data.inner[Math.floor(Math.random() * data.inner.length)];
  const kw2 = data.middle[Math.floor(Math.random() * data.middle.length)];
  const kw3 = data.outer[Math.floor(Math.random() * data.outer.length)];

  // Find matching strategy card
  const relevantStrategies = STRATEGY_CARDS.filter(s => 
    s.methods.some(m => m.includes(kw1) || m.includes(kw2) || m.includes(kw3)) ||
    s.trigger.includes(industry)
  );

  // Pick a hook template
  const hook = HOOK_TEMPLATES[Math.floor(Math.random() * HOOK_TEMPLATES.length)];
  const hookText = hook.formula
    .replace('【行业】', industry === 'default' ? '' : (INDUSTRY_DATA[industry] ? '' : ''))
    .replace('【反向操作】', '把成本翻倍')
    .replace('【具体结果】', `靠${kw1}月入翻倍`)
    .replace('【行业】', industry === 'default' ? '这个' : '')
    .replace('【动作】', '')
    .replace('【反常现象】', `${kw1}越贵${kw2}越不买`)
    .replace('【行业】', '')
    .replace('【时间】', '两分钟')
    .replace('【具体能力】', `掌握${kw1}核心方法`)
    .replace('【方法】', `${kw1}的${kw3}方法`)
    .replace('【好处1】', `${kw3}")
    .replace('【好处2】`, `提升${kw1}效果`)
    .replace('【行业】', '')
    .replace('【方法】', '')
    .replace('【事情】', `研究完${kw1}`);

  // Determine if flow or convert
  const isConvert = Math.random() > 0.6;
  const tag = isConvert ? '转化向' : '流量向';
  const tagClass = isConvert ? 'tag-convert' : 'tag-flow';

  // Build title
  const titlePatterns = [
    `${kw1}怎么做才能让${kw2}满意？`,
    `${kw2}最怕的${kw1}${kw3}方法`,
    `${kw1}和${kw3}，${kw2}该怎么选？`,
    `${kw2}必看：${kw1}${kw3}全攻略`,
    `揭秘${kw1}行业${kw3}内幕`,
    `${kw1}的${kw3}套路，${kw2}千万别踩坑`,
    `${kw2}做${kw1}，${kw3}才是关键`,
    `为什么${kw2}都选${kw1}？因为${kw3}`,
    `${kw1}不${kw3}，等于白做`,
    `3个${kw1}的${kw3}技巧，${kw2}照着做就行`
  ];
  const title = titlePatterns[Math.floor(Math.random() * titlePatterns.length)];

  // Reason
  const reasons = [
    `关键词"${kw1}"直击核心需求，"${kw2}"精准锁定人群`,
    `"${kw3}"是高频搜索词，配合"${kw1}"搜索量翻倍`,
    `"${kw2}"+"${kw1}"组合覆盖精准受众，避坑属性拉满`,
    `对比类内容天生高互动，"${kw1}vs${kw3}"引发讨论`,
    `揭秘型标题打开率最高，"${kw3}内幕"是流量密码`
  ];
  const reason = reasons[Math.floor(Math.random() * reasons.length)];

  return {
    title,
    hook: hookText,
    type: hook.name,
    tag,
    tagClass,
    keywords: [kw1, kw2, kw3],
    reason,
    strategy: relevantStrategies.length > 0 ? relevantStrategies[0].name : null
  };
}

// ============================================================
// WHEEL RENDERING
// ============================================================
function renderWheel() {
  const data = INDUSTRY_DATA[currentIndustry] || INDUSTRY_DATA.default;

  const outerEl = document.getElementById('outer-ring');
  const middleEl = document.getElementById('middle-ring');
  const innerEl = document.getElementById('inner-ring');

  outerEl.innerHTML = '';
  middleEl.innerHTML = '';
  innerEl.innerHTML = '';

  const cx = 300, cy = 300;

  // Create ring segments
  function createRing(el, items, radius, innerRadius) {
    const angleStep = (2 * Math.PI) / items.length;
    items.forEach((item, i) => {
      const startAngle = i * angleStep - Math.PI/2;
      const endAngle = (i + 1) * angleStep - Math.PI/2;

      const x1 = cx + innerRadius * Math.cos(startAngle);
      const y1 = cy + innerRadius * Math.sin(startAngle);
      const x2 = cx + radius * Math.cos(startAngle);
      const y2 = cy + radius * Math.sin(startAngle);
      const x3 = cx + radius * Math.cos(endAngle);
      const y3 = cy + radius * Math.sin(endAngle);
      const x4 = cx + innerRadius * Math.cos(endAngle);
      const y4 = cy + innerRadius * Math.sin(endAngle);

      const largeArc = angleStep > Math.PI ? 1 : 0;
      const d = `M${x1},${y1} L${x2},${y2} A${radius},${radius} 0 ${largeArc},1 ${x3},${y3} L${x4},${y4} A${innerRadius},${innerRadius} 0 ${largeArc},0 ${x1},${y1} Z`;

      const colors = ['#ff6a3c','#ff8a5c','#ffaa5c','#e85a3a','#d44a2a'];
      const color = colors[i % colors.length];

      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      path.setAttribute('d', d);
      path.setAttribute('fill', color);
      path.setAttribute('opacity', '0.15');
      path.setAttribute('stroke', color);
      path.setAttribute('stroke-width', '1');
      el.appendChild(path);

      // Text
      const midAngle = startAngle + angleStep/2;
      const textR = (radius + innerRadius) / 2;
      const tx = cx + textR * Math.cos(midAngle);
      const ty = cy + textR * Math.sin(midAngle);

      const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      text.setAttribute('x', tx);
      text.setAttribute('y', ty);
      text.setAttribute('text-anchor', 'middle');
      text.setAttribute('dominant-baseline', 'middle');
      text.setAttribute('font-size', item.length > 4 ? '9' : '11');
      text.setAttribute('fill', '#e0d8d0');
      text.setAttribute('transform', `rotate(${midAngle * 180/Math.PI + 90}, ${tx}, ${ty})`);
      text.textContent = item;
      el.appendChild(text);
    });
  }

  createRing(outerEl, data.outer, 270, 190);
  createRing(middleEl, data.middle, 175, 110);
  createRing(innerEl, data.inner, 95, 40);

  // Center text
  document.getElementById('center-text-1').textContent = data.inner[0];
  document.getElementById('center-text-2').textContent = data.middle[0];
}

// ============================================================
// WHEEL SPIN
// ============================================================
function spinWheel() {
  const data = INDUSTRY_DATA[currentIndustry] || INDUSTRY_DATA.default;

  const outerEl = document.getElementById('outer-ring');
  const middleEl = document.getElementById('middle-ring');
  const innerEl = document.getElementById('inner-ring');

  const randAngle = () => 360 * (3 + Math.random() * 5);

  gsap.to(innerEl, {
    rotation: `+=${randAngle()}`,
    transformOrigin: '300px 300px',
    duration: 2,
    ease: 'power4.out',
    onComplete: () => {
      const idx = Math.floor(Math.random() * data.inner.length);
      document.getElementById('center-text-1').textContent = data.inner[idx];
    }
  });

  gsap.to(middleEl, {
    rotation: `+=${randAngle() * 0.8}`,
    transformOrigin: '300px 300px',
    duration: 2.5,
    ease: 'power4.out',
    onComplete: () => {
      const idx = Math.floor(Math.random() * data.middle.length);
      document.getElementById('center-text-2').textContent = data.middle[idx];
    }
  });

  gsap.to(outerEl, {
    rotation: `+=${randAngle() * 0.6}`,
    transformOrigin: '300px 300px',
    duration: 3,
    ease: 'power4.out'
  });

  // Generate one topic after spin
  setTimeout(() => {
    const topic = generateTopic(currentIndustry);
    currentTopics.unshift(topic);
    renderTopics();
  }, 3100);
}

// ============================================================
// BATCH GENERATE
// ============================================================
function batchSpin(count) {
  const data = INDUSTRY_DATA[currentIndustry] || INDUSTRY_DATA.default;
  const newTopics = [];
  for (let i = 0; i < count; i++) {
    newTopics.push(generateTopic(currentIndustry));
  }
  currentTopics = [...newTopics, ...currentTopics];
  renderTopics();
  document.getElementById('spin-count').textContent = `已生成 ${currentTopics.length} 条选题`;

  // Quick visual flash
  gsap.to('#wheel-container', {
    scale: 0.98, duration: 0.1, yoyo: true, repeat: 1
  });
}

// ============================================================
// RENDER
// ============================================================
function renderTopics() {
  const grid = document.getElementById('topic-grid');
  const count = document.getElementById('topic-count');

  if (currentTopics.length === 0) {
    grid.innerHTML = '<div style="text-align:center;color:#6a5a4a;padding:3rem">点击"旋转匹配"或"批量生成"开始</div>';
    count.textContent = '共 0 条';
    return;
  }

  count.textContent = `共 ${currentTopics.length} 条`;

  grid.innerHTML = currentTopics.map(t => `
    <div class="topic-card">
      <div class="tag ${t.tagClass}">${t.tag}</div>
      <div class="title">${t.title}</div>
      <div class="meta">关键词：${t.keywords.map(k => `<span class="kw">${k}</span>`).join(' ')}</div>
      <div class="hook">${t.hook}</div>
      <div class="reason">${t.reason}</div>
      ${t.strategy ? `<div style="margin-top:0.4rem;font-size:0.75rem;color:#5a5a9a">策略参考：${t.strategy}</div>` : ''}
    </div>
  `).join('');

  document.getElementById('results').style.display = 'block';
  document.getElementById('wheel-section').style.display = 'block';

  // Animate cards
  gsap.from('.topic-card', {
    opacity:0, y:15, duration:0.3, stagger:0.02, ease:'power2.out'
  });
}

// ============================================================
// EXPORT
// ============================================================
function exportTopics() {
  if (currentTopics.length === 0) {
    alert('还没有生成选题，请先生成');
    return;
  }

  let text = `# 三环选题系统 - 导出报告\n`;
  text += `行业：${currentIndustry}\n`;
  text += `生成时间：${new Date().toLocaleString('zh-CN', {timeZone:'Asia/Shanghai'})}\n`;
  text += `共 ${currentTopics.length} 条\n\n`;

  currentTopics.forEach((t, i) => {
    text += `---\n`;
    text += `## ${i+1}. ${t.title}\n`;
    text += `类型：${t.tag} | 钩子模板：${t.type}\n`;
    text += `关键词：${t.keywords.join('、')}\n`;
    text += `钩子：${t.hook}\n`;
    text += `策略：${t.reason}\n`;
    if (t.strategy) text += `参考策略卡：${t.strategy}\n`;
    text += '\n';
  });

  const blob = new Blob([text], {type:'text/plain;charset=utf-8'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `三环选题-${currentIndustry}-${Date.now()}.md`;
  a.click();
  URL.revokeObjectURL(a.href);
}

// ============================================================
// MAIN
// ============================================================
function generateTopics() {
  const input = document.getElementById('industry-input').value.trim();

  // Auto-detect industry
  if (input.includes('婚礼') || input.includes('婚庆') || input.includes('结婚')) {
    currentIndustry = 'wedding';
  } else if (input.includes('门窗') || input.includes('窗户') || input.includes('阳光房')) {
    currentIndustry = 'door_window';
  } else if (input.includes('餐饮') || input.includes('饭店') || input.includes('餐厅') || input.includes('美食')) {
    currentIndustry = 'catering';
  } else if (input.includes('摄影') || input.includes('拍照') || input.includes('相机')) {
    currentIndustry = 'photography';
  } else {
    currentIndustry = 'default';
  }

  document.getElementById('wheel-title').textContent = `三环旋转匹配中 — ${input || '通用'}`;
  document.getElementById('wheel-sub').textContent = '内圈：产品层 · 中圈：用户层 · 外圈：需求痛点层';

  renderWheel();
  document.getElementById('wheel-section').style.display = 'block';

  // Scroll to wheel
  document.getElementById('wheel-section').scrollIntoView({behavior:'smooth'});

  // Auto-generate initial 10
  batchSpin(10);
}

// ============================================================
// STRATEGY PANEL
// ============================================================
function showStrategies() {
  document.getElementById('results').style.display = 'none';
  document.getElementById('strategy-panel').style.display = 'block';
  document.getElementById('hook-panel').style.display = 'none';

  const list = document.getElementById('strategy-list');
  list.innerHTML = STRATEGY_CARDS.map(s => `
    <div class="strategy-card">
      <h3>${s.name}</h3>
      <div class="desc">${s.desc}</div>
      <ul class="methods">
        ${s.methods.map(m => `<li>${m}</li>`).join('')}
      </ul>
      <div style="margin-top:0.5rem;font-size:0.75rem;color:#5a5a9a">触发条件：${s.trigger}</div>
    </div>
  `).join('');

  document.getElementById('strategy-panel').scrollIntoView({behavior:'smooth'});
}

function showHooks() {
  document.getElementById('results').style.display = 'none';
  document.getElementById('strategy-panel').style.display = 'none';
  document.getElementById('hook-panel').style.display = 'block';

  const grid = document.getElementById('hook-grid');
  grid.innerHTML = HOOK_TEMPLATES.map((h, i) => `
    <div class="hook-card">
      <div class="num">${i+1}</div>
      <div class="name">${h.name}</div>
      <div class="formula">${h.formula}</div>
      <div class="example">${h.example}</div>
    </div>
  `).join('');

  document.getElementById('hook-panel').scrollIntoView({behavior:'smooth'});
}

function showResults() {
  document.getElementById('strategy-panel').style.display = 'none';
  document.getElementById('hook-panel').style.display = 'none';
  document.getElementById('results').style.display = 'block';
}

// ============================================================
// INIT
// ============================================================
renderWheel();
renderTopics();

// GSAP hero animation
gsap.from('.hero h1', {opacity:0, y:30, duration:1, ease:'power2.out'});
gsap.from('.hero .sub', {opacity:0, y:20, duration:1, delay:0.2, ease:'power2.out'});
gsap.from('.hero .input-area', {opacity:0, y:15, duration:0.8, delay:0.4, ease:'power2.out'});
</script>
</body>
</html>
